-- Validation for the core model: run AFTER loading. Generated by `python -m backend.database.hana_core`; do not edit. Change hana_core_spec.py and regenerate.
--
-- One result set per group. Every row is (CHECK_GROUP, CHECK_NAME, TABLE_NAME, SEVERITY, ACTUAL, EXPECTED, OUTCOME).
-- OUTCOME is PASS when ACTUAL = EXPECTED. A FAIL is a real problem. A WARN is a known, documented property of the data
-- (e.g. tariff values above 50% that the World Bank publishes); it should still match its EXPECTED count.
-- Run with the same current schema as the DDL. Only three constructs are HANA-specific: TO_DATE, MONTH and ADD_DAYS.
-- NOT YET RUN ON A HANA TENANT; the same checks, with the SQLite equivalents of those three, are exercised by the tests.

-- ROW_COUNT
SELECT 'ROW_COUNT' AS CHECK_GROUP, 'COUNTRY has 217 rows' AS CHECK_NAME, 'COUNTRY' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 217 AS EXPECTED, CASE WHEN COUNT(*) = 217 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "COUNTRY"
UNION ALL
