  FROM "DEMAND" WHERE "DATE" IS NULL OR "DATE" < TO_DATE('2010-12-01', 'YYYY-MM-DD') OR "DATE" > TO_DATE('2011-12-09', 'YYYY-MM-DD')
UNION ALL
SELECT 'DATES' AS CHECK_GROUP, 'INVENTORY: DATE is present and inside the cleaned window 2010-12-01 to 2011-12-09' AS CHECK_NAME, 'INVENTORY' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "INVENTORY" WHERE "DATE" IS NULL OR "DATE" < TO_DATE('2010-12-01', 'YYYY-MM-DD') OR "DATE" > TO_DATE('2011-12-09', 'YYYY-MM-DD')
UNION ALL
SELECT 'DATES' AS CHECK_GROUP, 'DEMAND_MODELING_PANEL: DATE is present and inside the cleaned window 2010-12-01 to 2011-12-09' AS CHECK_NAME, 'DEMAND_MODELING_PANEL' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "DEMAND_MODELING_PANEL" WHERE "DATE" IS NULL OR "DATE" < TO_DATE('2010-12-01', 'YYYY-MM-DD') OR "DATE" > TO_DATE('2011-12-09', 'YYYY-MM-DD')
UNION ALL
SELECT 'DATES' AS CHECK_GROUP, 'PRODUCT: sale dates inside 2010-12-01 to 2011-12-09 and FIRST_SALE_DATE not after LAST_SALE_DATE' AS CHECK_NAME, 'PRODUCT' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "PRODUCT" WHERE "FIRST_SALE_DATE" < TO_DATE('2010-12-01', 'YYYY-MM-DD') OR "LAST_SALE_DATE" > TO_DATE('2011-12-09', 'YYYY-MM-DD') OR "FIRST_SALE_DATE" > "LAST_SALE_DATE"
UNION ALL
SELECT 'DATES' AS CHECK_GROUP, 'DISRUPTION_EVENT: an event does not end before it starts' AS CHECK_NAME, 'DISRUPTION_EVENT' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
