UNION ALL
SELECT 'DATES' AS CHECK_GROUP, 'TARIFF: EFFECTIVE_YEAR is between 1960 and 2100' AS CHECK_NAME, 'TARIFF' AS TABLE_NAME, 'ERROR' AS SEVERITY,
