  FROM "TARIFF" WHERE "EFFECTIVE_YEAR" NOT BETWEEN 1960 AND 2100
UNION ALL
SELECT 'DATES' AS CHECK_GROUP, 'DEMAND_MODELING_PANEL: MONTH agrees with DATE' AS CHECK_NAME, 'DEMAND_MODELING_PANEL' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
