SELECT 'TARIFF_RANGE' AS CHECK_GROUP, 'TARIFF: no negative rate' AS CHECK_NAME, 'TARIFF' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "TARIFF" WHERE "TARIFF_RATE_PCT" < 0
UNION ALL
SELECT 'TARIFF_RANGE' AS CHECK_GROUP, 'TARIFF: no rate above 50% that is not flagged EXTREME_VALUE' AS CHECK_NAME, 'TARIFF' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "TARIFF" WHERE "TARIFF_RATE_PCT" > 50 AND "QUALITY_FLAG" NOT LIKE 'EXTREME%'
UNION ALL
SELECT 'TARIFF_RANGE' AS CHECK_GROUP, 'TARIFF: no rate flagged EXTREME_VALUE at or below 50%' AS CHECK_NAME, 'TARIFF' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "TARIFF" WHERE "QUALITY_FLAG" LIKE 'EXTREME%' AND "TARIFF_RATE_PCT" <= 50
UNION ALL
SELECT 'TARIFF_RANGE' AS CHECK_GROUP, 'TARIFF: 9 rates above 50% are flagged EXTREME_VALUE (source values, kept as published)' AS CHECK_NAME, 'TARIFF' AS TABLE_NAME, 'WARN' AS SEVERITY,
       COUNT(*) AS ACTUAL, 9 AS EXPECTED, CASE WHEN COUNT(*) = 9 THEN 'PASS' ELSE 'WARN' END AS OUTCOME
  FROM "TARIFF" WHERE "QUALITY_FLAG" LIKE 'EXTREME%'
UNION ALL
SELECT 'TARIFF_RANGE' AS CHECK_GROUP, 'TARIFF: 4 rates above 100% (source values, kept as published)' AS CHECK_NAME, 'TARIFF' AS TABLE_NAME, 'WARN' AS SEVERITY,
