  FROM "TARIFF" WHERE "TARIFF_RATE_PCT" > 100;

-- CONSISTENCY
SELECT 'CONSISTENCY' AS CHECK_GROUP, 'INVENTORY: closing = opening + inbound - outbound' AS CHECK_NAME, 'INVENTORY' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "INVENTORY" WHERE "CLOSING_STOCK" <> "OPENING_STOCK" + "INBOUND_QUANTITY" - "OUTBOUND_QUANTITY"
UNION ALL
SELECT 'CONSISTENCY' AS CHECK_GROUP, 'INVENTORY: outbound + unfilled = demand (no lost sale is hidden)' AS CHECK_NAME, 'INVENTORY' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "INVENTORY" WHERE "OUTBOUND_QUANTITY" + "UNFILLED_QUANTITY" <> "DEMAND_QUANTITY"
UNION ALL
SELECT 'CONSISTENCY' AS CHECK_GROUP, 'INVENTORY: STOCKOUT_FLAG is set exactly when UNFILLED_QUANTITY > 0' AS CHECK_NAME, 'INVENTORY' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "INVENTORY" WHERE ("STOCKOUT_FLAG" = TRUE AND "UNFILLED_QUANTITY" = 0) OR ("STOCKOUT_FLAG" = FALSE AND "UNFILLED_QUANTITY" > 0)
UNION ALL
SELECT 'CONSISTENCY' AS CHECK_GROUP, 'INVENTORY: each day opens with the previous day''s closing stock' AS CHECK_NAME, 'INVENTORY' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "INVENTORY" A JOIN "INVENTORY" B ON B."WAREHOUSE_ID" = A."WAREHOUSE_ID" AND B."PRODUCT_ID" = A."PRODUCT_ID" AND B."DATE" = ADD_DAYS(A."DATE", 1) WHERE B."OPENING_STOCK" <> A."CLOSING_STOCK"
UNION ALL
SELECT 'CONSISTENCY' AS CHECK_GROUP, 'INVENTORY: the warehouses'' demand adds up to the panel''s demand on every product-day' AS CHECK_NAME, 'INVENTORY' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM (SELECT "PRODUCT_ID", "DATE", SUM("DEMAND_QUANTITY") AS TOTAL FROM "INVENTORY" GROUP BY "PRODUCT_ID", "DATE") X JOIN "DEMAND_MODELING_PANEL" P ON P."PRODUCT_ID" = X."PRODUCT_ID" AND P."DATE" = X."DATE" WHERE P."DEMAND_QUANTITY" <> X.TOTAL
UNION ALL
SELECT 'CONSISTENCY' AS CHECK_GROUP, 'INVENTORY: complete grid (warehouses x products x days)' AS CHECK_NAME, 'INVENTORY' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM (SELECT COUNT(*) AS N, COUNT(DISTINCT "WAREHOUSE_ID") AS W, COUNT(DISTINCT "PRODUCT_ID") AS P, COUNT(DISTINCT "DATE") AS D FROM "INVENTORY") X WHERE X.N <> X.W * X.P * X.D
UNION ALL
SELECT 'CONSISTENCY' AS CHECK_GROUP, 'DEMAND_MODELING_PANEL: dense calendar (products x days)' AS CHECK_NAME, 'DEMAND_MODELING_PANEL' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM (SELECT COUNT(*) AS N, COUNT(DISTINCT "PRODUCT_ID") AS P, COUNT(DISTINCT "DATE") AS D FROM "DEMAND_MODELING_PANEL") X WHERE X.N <> X.P * X.D
UNION ALL
SELECT 'CONSISTENCY' AS CHECK_GROUP, 'PRODUCT: IS_FORECAST_SERIES marks exactly the panel''s products' AS CHECK_NAME, 'PRODUCT' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM (SELECT COUNT(*) AS N FROM "PRODUCT" WHERE "IS_FORECAST_SERIES" = TRUE) X WHERE X.N <> (SELECT COUNT(DISTINCT "PRODUCT_ID") FROM "DEMAND_MODELING_PANEL")
UNION ALL
SELECT 'CONSISTENCY' AS CHECK_GROUP, 'INVENTORY_POLICY: the warehouses'' demand shares sum to 1' AS CHECK_NAME, 'INVENTORY_POLICY' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM (SELECT SUM("DEMAND_SHARE") AS S FROM "INVENTORY_POLICY") X WHERE ABS(X.S - 1) > 0.0001
UNION ALL
SELECT 'CONSISTENCY' AS CHECK_GROUP, 'SCENARIO: BASELINE_NORMAL exists' AS CHECK_NAME, 'SCENARIO' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 1 AS EXPECTED, CASE WHEN COUNT(*) = 1 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "SCENARIO" WHERE "SCENARIO_ID" = 'BASELINE_NORMAL'
UNION ALL
SELECT 'CONSISTENCY' AS CHECK_GROUP, 'SCENARIO_STATE: BASELINE_NORMAL changes nothing (every supplier ACTIVE, every lane NORMAL)' AS CHECK_NAME, 'SCENARIO_STATE' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "SCENARIO_STATE" WHERE "SCENARIO_ID" = 'BASELINE_NORMAL'
UNION ALL
SELECT 'CONSISTENCY' AS CHECK_GROUP, 'SUPPLIER: every supplier carries at least one product' AS CHECK_NAME, 'SUPPLIER' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "SUPPLIER" S WHERE NOT EXISTS (SELECT 1 FROM "SUPPLIER_PRODUCT" SP WHERE SP."SUPPLIER_ID" = S."SUPPLIER_ID")
UNION ALL
SELECT 'CONSISTENCY' AS CHECK_GROUP, 'SUPPLIER_PRODUCT: every product with a supplier has at least two' AS CHECK_NAME, 'SUPPLIER_PRODUCT' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM (SELECT "PRODUCT_ID" FROM "SUPPLIER_PRODUCT" GROUP BY "PRODUCT_ID" HAVING COUNT(*) < 2) X
UNION ALL
SELECT 'CONSISTENCY' AS CHECK_GROUP, 'ROUTE: every SUEZ lane has a CAPE lane between the same ports' AS CHECK_NAME, 'ROUTE' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "ROUTE" S WHERE S."VIA" = 'SUEZ' AND NOT EXISTS (SELECT 1 FROM "ROUTE" C WHERE C."VIA" = 'CAPE' AND C."ORIGIN_PORT_ID" = S."ORIGIN_PORT_ID" AND C."DESTINATION_PORT_ID" = S."DESTINATION_PORT_ID")
UNION ALL
SELECT 'CONSISTENCY' AS CHECK_GROUP, 'ROUTE: a CAPE lane is longer than the SUEZ lane between the same ports' AS CHECK_NAME, 'ROUTE' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 0 AS EXPECTED, CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "ROUTE" S JOIN "ROUTE" C ON C."VIA" = 'CAPE' AND S."VIA" = 'SUEZ' AND C."ORIGIN_PORT_ID" = S."ORIGIN_PORT_ID" AND C."DESTINATION_PORT_ID" = S."DESTINATION_PORT_ID" WHERE C."DISTANCE_KM" <= S."DISTANCE_KM";

-- CONTROL_TOTALS
SELECT 'CONTROL_TOTALS' AS CHECK_GROUP, 'DEMAND: SUM(DEMAND_QUANTITY) = 5,308,637, as in the cleaned CSV' AS CHECK_NAME, 'DEMAND' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       SUM("DEMAND_QUANTITY") AS ACTUAL, 5308637 AS EXPECTED, CASE WHEN SUM("DEMAND_QUANTITY") = 5308637 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "DEMAND"
UNION ALL
SELECT 'CONTROL_TOTALS' AS CHECK_GROUP, 'DEMAND_MODELING_PANEL: SUM(DEMAND_QUANTITY) = 766,802, as in the cleaned CSV' AS CHECK_NAME, 'DEMAND_MODELING_PANEL' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       SUM("DEMAND_QUANTITY") AS ACTUAL, 766802 AS EXPECTED, CASE WHEN SUM("DEMAND_QUANTITY") = 766802 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "DEMAND_MODELING_PANEL"
UNION ALL
SELECT 'CONTROL_TOTALS' AS CHECK_GROUP, 'INVENTORY: SUM(DEMAND_QUANTITY) = 766,802, as in the cleaned CSV' AS CHECK_NAME, 'INVENTORY' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       SUM("DEMAND_QUANTITY") AS ACTUAL, 766802 AS EXPECTED, CASE WHEN SUM("DEMAND_QUANTITY") = 766802 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "INVENTORY"
UNION ALL
SELECT 'CONTROL_TOTALS' AS CHECK_GROUP, 'INVENTORY: SUM(OUTBOUND_QUANTITY) = 762,945, as in the cleaned CSV' AS CHECK_NAME, 'INVENTORY' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       SUM("OUTBOUND_QUANTITY") AS ACTUAL, 762945 AS EXPECTED, CASE WHEN SUM("OUTBOUND_QUANTITY") = 762945 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "INVENTORY"
UNION ALL
SELECT 'CONTROL_TOTALS' AS CHECK_GROUP, 'INVENTORY: SUM(UNFILLED_QUANTITY) = 3,857, as in the cleaned CSV' AS CHECK_NAME, 'INVENTORY' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       SUM("UNFILLED_QUANTITY") AS ACTUAL, 3857 AS EXPECTED, CASE WHEN SUM("UNFILLED_QUANTITY") = 3857 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "INVENTORY"
UNION ALL
SELECT 'CONTROL_TOTALS' AS CHECK_GROUP, 'PRODUCT: SUM(NET_UNITS) = 5,308,637, as in the cleaned CSV' AS CHECK_NAME, 'PRODUCT' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       SUM("NET_UNITS") AS ACTUAL, 5308637 AS EXPECTED, CASE WHEN SUM("NET_UNITS") = 5308637 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "PRODUCT"
UNION ALL
SELECT 'CONTROL_TOTALS' AS CHECK_GROUP, 'INVENTORY: 26 stock-out days' AS CHECK_NAME, 'INVENTORY' AS TABLE_NAME, 'ERROR' AS SEVERITY,
       COUNT(*) AS ACTUAL, 26 AS EXPECTED, CASE WHEN COUNT(*) = 26 THEN 'PASS' ELSE 'FAIL' END AS OUTCOME
  FROM "INVENTORY" WHERE "STOCKOUT_FLAG" = TRUE;
